 public ObservableCollection<ProductionActualRow> Actuals{get;}=new();public ICollectionView ActualsView{get;}public ObservableCollection<ProductionOrderActualOption> Orders{get;}=new();public ObservableCollection<DowntimeEntryRow> Downtimes{get;}=new();public IReadOnlyList<string> DowntimeReasons{get;}=new[]{"Störung","Materialmangel","Umrüstung","Reinigung","Qualität","Personal","Wartung","Sonstiges"};
 [ObservableProperty]private ProductionActualRow? selectedActual;[ObservableProperty]private string searchText=string.Empty;[ObservableProperty]private string articleNumber=string.Empty;[ObservableProperty]private string batchNumber=string.Empty;[ObservableProperty]private ProductionOrderActualOption? selectedOrder;[ObservableProperty]private DowntimeEntryRow? selectedDowntime;[ObservableProperty]private DateTime actualDate=DateTime.Today;[ObservableProperty]private double totalQuantity;[ObservableProperty]private double goodQuantity;[ObservableProperty]private double scrapQuantity;[ObservableProperty]private double plannedProductionMinutes=450;[ObservableProperty]private double runMinutes;[ObservableProperty]private double idealRatePerHour=1;[ObservableProperty]private string comment=string.Empty;[ObservableProperty]private string downtimeReason="Störung";[ObservableProperty]private double downtimeMinutes;[ObservableProperty]private string downtimeComment=string.Empty;[ObservableProperty]private string statusMessage=string.Empty;[ObservableProperty]private string availabilityText="0.0 %";[ObservableProperty]private string performanceText="0.0 %";[ObservableProperty]private string qualityText="0.0 %";[ObservableProperty]private string oeeText="0.0 %";[ObservableProperty]private string theoreticalQuantityText="0";
 public ProductionActualViewModel(){ActualsView=CollectionViewSource.GetDefaultView(Actuals);ActualsView.Filter=MatchesActualFilter;LoadOrders();LoadActuals();NewActual();}partial void OnSearchTextChanged(string value)=>ActualsView.Refresh();partial void OnSelectedActualChanged(ProductionActualRow? value){if(value is null)return;SelectedOrder=Orders.FirstOrDefault(x=>x.RunSlotId==value.ProductionRunSlotId)??Orders.FirstOrDefault(x=>x.Id==value.ProductionOrderId);ActualDate=value.Date;ArticleNumber=value.ArticleNumber;BatchNumber=value.BatchNumber;TotalQuantity=value.TotalQuantity;GoodQuantity=value.GoodQuantity;ScrapQuantity=value.ScrapQuantity;PlannedProductionMinutes=value.PlannedProductionMinutes;RunMinutes=value.RunMinutes;IdealRatePerHour=value.IdealRatePerHour;Comment=value.Comment??"";StatusMessage=value.ProductionRunSlotId.HasValue?"":"Legacy-Erfassung: keine eindeutige Produktionsschicht zuordenbar.";LoadDowntimes(value.Id);RefreshPreview();}partial void OnSelectedOrderChanged(ProductionOrderActualOption? value){if(value is null||SelectedActual is not null)return;ApplyOrderDefaults(value);}partial void OnPlannedProductionMinutesChanged(double value)=>RefreshPreview();partial void OnRunMinutesChanged(double value)=>RefreshPreview();partial void OnTotalQuantityChanged(double value)=>RefreshPreview();partial void OnGoodQuantityChanged(double value)=>RefreshPreview();partial void OnIdealRatePerHourChanged(double value)=>RefreshPreview();
 [RelayCommand]private void NewActual(){SelectedActual=null;SelectedDowntime=null;Downtimes.Clear();SelectedOrder=Orders.FirstOrDefault(x=>!focusedOrderId.HasValue||x.Id==focusedOrderId);ActualDate=SelectedOrder?.PlannedDate??DateTime.Today;ArticleNumber=SelectedOrder?.ArticleNumber??string.Empty;BatchNumber=string.Empty;TotalQuantity=GoodQuantity=ScrapQuantity=0;Comment="";DowntimeReason="Störung";DowntimeMinutes=0;DowntimeComment="";StatusMessage="";if(SelectedOrder is not null)ApplyOrderDefaults(SelectedOrder);else{PlannedProductionMinutes=450;RunMinutes=0;IdealRatePerHour=1;}RefreshPreview();}
 [RelayCommand]private void Save(){if(SelectedOrder is null||!SelectedOrder.RunSlotId.HasValue){StatusMessage="Bitte eine konkrete Auftragsschicht auswählen.";return;}if(!double.IsFinite(PlannedProductionMinutes)||PlannedProductionMinutes<=0){StatusMessage="Die geplante Produktionszeit muss grösser als 0 sein.";return;}if(!double.IsFinite(RunMinutes)||RunMinutes<0||RunMinutes>PlannedProductionMinutes){StatusMessage="Die Laufzeit muss zwischen 0 und der geplanten Produktionszeit liegen.";return;}if(!double.IsFinite(TotalQuantity)||!double.IsFinite(GoodQuantity)||!double.IsFinite(ScrapQuantity)||TotalQuantity<0||GoodQuantity<0||ScrapQuantity<0){StatusMessage="Mengen müssen endliche, nicht negative Zahlen sein.";return;}if(GoodQuantity>TotalQuantity||ScrapQuantity>TotalQuantity||Math.Abs(TotalQuantity-(GoodQuantity+ScrapQuantity))>0.01){StatusMessage="Gesamtmenge muss Gutmenge + Ausschuss entsprechen.";return;}if(!double.IsFinite(IdealRatePerHour)||IdealRatePerHour<=0){StatusMessage="Die Sollrate pro Stunde muss eine endliche Zahl grösser als 0 sein.";return;}using var db=new AppDbContext();var slot=db.ProductionRunSlots.AsNoTracking().Include(x=>x.Shift).Include(x=>x.ProductionOrder).ThenInclude(x=>x.Workstation).FirstOrDefault(x=>x.Id==SelectedOrder.RunSlotId.Value&&x.ProductionOrderId==SelectedOrder.Id);if(slot is null){StatusMessage="Die ausgewählte Produktionsschicht existiert nicht mehr.";return;}if(!CanChange(db,slot.ProductionOrderId))return;if(SelectedActual is not null&&!CanChange(db,db.ProductionActuals.Where(x=>x.Id==SelectedActual.Id).Select(x=>x.ProductionOrderId).Single()))return;ProductionActual e;if(SelectedActual is null){e=new();db.ProductionActuals.Add(e);}else e=db.ProductionActuals.First(x=>x.Id==SelectedActual.Id);if(SelectedActual is not null&&e.ProductionOrderId!=SelectedOrder.Id){StatusMessage="Historische Ist-Erfassungen dürfen nicht einer anderen Charge zugeordnet werden.";return;}var dt=db.DowntimeEntries.Where(x=>x.ProductionActualId==e.Id).Sum(x=>x.Minutes);if(dt>PlannedProductionMinutes-RunMinutes+0.01){StatusMessage="Die gespeicherten Stillstände überschreiten die neue Verlustzeit.";return;}e.ProductionOrderId=SelectedOrder.Id;e.ProductionRunSlotId=slot.Id;e.Date=slot.Date.Date;if(SelectedActual is null){e.ArticleNumberSnapshot=slot.ProductionOrder.ArticleNumber;e.BatchNumber=slot.ProductionOrder.BatchNumber;}e.TotalQuantity=TotalQuantity;e.GoodQuantity=GoodQuantity;e.ScrapQuantity=ScrapQuantity;e.PlannedProductionMinutes=PlannedProductionMinutes;e.RunMinutes=RunMinutes;e.IdealRatePerHour=IdealRatePerHour;if(SelectedActual is null||string.IsNullOrWhiteSpace(e.ProductSnapshot)){e.ProductSnapshot=slot.ProductionOrder.Product;e.UnitSnapshot=slot.ProductionOrder.Unit;e.WorkstationIdSnapshot=slot.ProductionOrder.WorkstationId;e.WorkstationNameSnapshot=slot.ProductionOrder.Workstation.Name;e.ShiftNameSnapshot=slot.Shift.Name;}e.Comment=string.IsNullOrWhiteSpace(Comment)?null:Comment.Trim();db.SaveChanges();LoadActuals(e.Id);StatusMessage="Ist-Produktion der konkreten Auftragsschicht gespeichert.";}
 [RelayCommand]private void DeleteActual(){if(SelectedActual is null){StatusMessage="Bitte zuerst eine Ist-Erfassung auswählen.";return;}using var db=new AppDbContext();var e=db.ProductionActuals.FirstOrDefault(x=>x.Id==SelectedActual.Id);if(e is null){LoadActuals();return;}if(!CanChange(db,e.ProductionOrderId))return;db.ProductionActuals.Remove(e);db.SaveChanges();LoadActuals();NewActual();StatusMessage="Ist-Erfassung inklusive Stillstandsdetails gelöscht.";}[RelayCommand]private void AddDowntime(){if(SelectedActual is null){StatusMessage="Bitte die Ist-Erfassung zuerst speichern.";return;}if(!double.IsFinite(DowntimeMinutes)||DowntimeMinutes<=0){StatusMessage="Die Stillstandsdauer muss eine endliche Zahl grösser als 0 sein.";return;}using var db=new AppDbContext();var a=db.ProductionActuals.FirstOrDefault(x=>x.Id==SelectedActual.Id);if(a is null)return;if(!CanChange(db,a.ProductionOrderId))return;var loss=Math.Max(0,a.PlannedProductionMinutes-a.RunMinutes);var existing=db.DowntimeEntries.Where(x=>x.ProductionActualId==a.Id).Sum(x=>x.Minutes);if(existing+DowntimeMinutes>loss+0.01){StatusMessage=$"Stillstandszeiten überschreiten die verfügbare Verlustzeit von {loss:N0} Minuten.";return;}db.DowntimeEntries.Add(new DowntimeEntry{ProductionActualId=a.Id,Reason=DowntimeReason,Minutes=DowntimeMinutes,Comment=string.IsNullOrWhiteSpace(DowntimeComment)?null:DowntimeComment.Trim()});db.SaveChanges();DowntimeMinutes=0;DowntimeComment="";LoadDowntimes(a.Id);LoadActuals(a.Id);StatusMessage="Stillstand erfasst.";}[RelayCommand]private void DeleteDowntime(){if(SelectedDowntime is null)return;using var db=new AppDbContext();var e=db.DowntimeEntries.FirstOrDefault(x=>x.Id==SelectedDowntime.Id);if(e is null)return;var id=e.ProductionActualId;if(!CanChange(db,db.ProductionActuals.Where(x=>x.Id==id).Select(x=>x.ProductionOrderId).Single()))return;db.DowntimeEntries.Remove(e);db.SaveChanges();LoadDowntimes(id);LoadActuals(id);StatusMessage="Stillstand gelöscht.";}[RelayCommand]private void Refresh(){var id=SelectedActual?.Id;LoadOrders();LoadActuals(id);StatusMessage="Ist-Produktion aktualisiert.";}
 private void ApplyOrderDefaults(ProductionOrderActualOption o){ArticleNumber=o.ArticleNumber;BatchNumber=o.BatchNumber;ActualDate=o.PlannedDate;PlannedProductionMinutes=o.PlannedProductionMinutes>0?o.PlannedProductionMinutes:450;RunMinutes=PlannedProductionMinutes;IdealRatePerHour=o.DefaultIdealRatePerHour>0?o.DefaultIdealRatePerHour:1;}
 private void LoadOrders(){using var db=new AppDbContext();ProductionScheduleService.EnsureMissingRunSlots(db);var selectedSlot=SelectedOrder?.RunSlotId;var slots=db.ProductionRunSlots.AsNoTracking().Include(x=>x.Shift).Include(x=>x.ProductionOrder).ThenInclude(x=>x.Workstation).AsEnumerable().OrderByDescending(x=>x.Date).ThenBy(x=>x.Shift.StartTime).ThenBy(x=>x.Id).ToList();var orderIds=slots.Select(x=>x.ProductionOrderId).Distinct().ToArray();var totalMinutes=slots.Where(x=>orderIds.Contains(x.ProductionOrderId)).GroupBy(x=>x.ProductionOrderId).ToDictionary(g=>g.Key,g=>g.Sum(x=>CalculatePlannedMinutes(x.Shift,null,null)));Orders.Clear();foreach(var s in slots){var minutes=CalculatePlannedMinutes(s.Shift,null,null);var fullRunMinutes=totalMinutes.GetValueOrDefault(s.ProductionOrderId);var rate=fullRunMinutes>0&&s.ProductionOrder.Quantity>0?s.ProductionOrder.Quantity/(fullRunMinutes/60d):1;Orders.Add(new ProductionOrderActualOption{Id=s.ProductionOrderId,RunSlotId=s.Id,SequenceNumber=s.SequenceNumber,OrderNumber=s.ProductionOrder.OrderNumber,Product=s.ProductionOrder.Product,Unit=s.ProductionOrder.Unit,ArticleNumber=s.ProductionOrder.ArticleNumber,BatchNumber=s.ProductionOrder.BatchNumber,PlannedDate=s.Date,WorkstationName=s.ProductionOrder.Workstation.Name,ShiftName=s.Shift.Name,PlannedProductionMinutes=minutes,DefaultIdealRatePerHour=s.ProductionOrder.IdealRatePerHourSnapshot??rate});}SelectedOrder=Orders.FirstOrDefault(x=>x.RunSlotId==selectedSlot)??Orders.FirstOrDefault();}
 private bool MatchesActualFilter(object item){if(item is not ProductionActualRow row)return false;if(focusedOrderId.HasValue&&row.ProductionOrderId!=focusedOrderId)return false;var term=SearchText?.Trim();if(string.IsNullOrWhiteSpace(term))return true;return row.ArticleNumber.Contains(term,StringComparison.OrdinalIgnoreCase)||row.BatchNumber.Contains(term,StringComparison.OrdinalIgnoreCase)||row.OrderNumber.Contains(term,StringComparison.OrdinalIgnoreCase)||row.Product.Contains(term,StringComparison.OrdinalIgnoreCase)||row.WorkstationName.Contains(term,StringComparison.OrdinalIgnoreCase);}
 private void LoadActuals(int? selectId=null){using var db=new AppDbContext();var items=db.ProductionActuals.AsNoTracking().Include(x=>x.ProductionOrder).ThenInclude(x=>x.Workstation).Include(x=>x.ProductionOrder).ThenInclude(x=>x.Shift).Include(x=>x.ProductionRunSlot).ThenInclude(x=>x!.Shift).Include(x=>x.Downtimes).OrderByDescending(x=>x.Date).ToList();Actuals.Clear();foreach(var i in items){var m=OeeAnalyticsService.Calculate(i.PlannedProductionMinutes,i.RunMinutes,i.TotalQuantity,i.GoodQuantity,i.IdealRatePerHour);Actuals.Add(new ProductionActualRow{Id=i.Id,ProductionOrderId=i.ProductionOrderId,ProductionRunSlotId=i.ProductionRunSlotId,Date=i.Date,OrderNumber=i.ProductionOrder.OrderNumber,Product=i.ProductSnapshot??i.ProductionOrder.Product,Unit=i.UnitSnapshot??i.ProductionOrder.Unit,ArticleNumber=i.ArticleNumberSnapshot??i.ProductionOrder.ArticleNumber,BatchNumber=i.BatchNumber??string.Empty,WorkstationName=i.WorkstationNameSnapshot??i.ProductionOrder.Workstation.Name,ShiftName=i.ShiftNameSnapshot??i.ProductionRunSlot?.Shift.Name??"Legacy / nicht eindeutig",TotalQuantity=i.TotalQuantity,GoodQuantity=i.GoodQuantity,ScrapQuantity=i.ScrapQuantity,PlannedProductionMinutes=i.PlannedProductionMinutes,RunMinutes=i.RunMinutes,DowntimeMinutes=i.Downtimes.Sum(x=>x.Minutes),IdealRatePerHour=i.IdealRatePerHour,AvailabilityPercent=m.AvailabilityPercent,PerformancePercent=m.PerformancePercent,QualityPercent=m.QualityPercent,OeePercent=m.OeePercent,Comment=i.Comment});}SelectedActual=selectId.HasValue?Actuals.FirstOrDefault(x=>x.Id==selectId):null;}private void LoadDowntimes(int id){using var db=new AppDbContext();var items=db.DowntimeEntries.AsNoTracking().Where(x=>x.ProductionActualId==id).OrderByDescending(x=>x.Minutes).ToList();Downtimes.Clear();foreach(var i in items)Downtimes.Add(new DowntimeEntryRow{Id=i.Id,ProductionActualId=i.ProductionActualId,Reason=i.Reason,Minutes=i.Minutes,Comment=i.Comment});}private void RefreshPreview(){var m=OeeAnalyticsService.Calculate(PlannedProductionMinutes,RunMinutes,TotalQuantity,GoodQuantity,IdealRatePerHour);AvailabilityText=$"{m.AvailabilityPercent:N1} %";PerformanceText=$"{m.PerformancePercent:N1} %";QualityText=$"{m.QualityPercent:N1} %";OeeText=$"{m.OeePercent:N1} %";TheoreticalQuantityText=$"{m.TheoreticalQuantity:N0}";}private static double CalculatePlannedMinutes(Shift? s,TimeSpan? ps,TimeSpan? pe){if(s is not null){var a=DateTime.Today+s.StartTime;var b=DateTime.Today+s.EndTime;if(b<=a)b=b.AddDays(1);return Math.Max(0,(b-a).TotalMinutes-s.BreakMinutes);}if(ps.HasValue&&pe.HasValue){var a=DateTime.Today+ps.Value;var b=DateTime.Today+pe.Value;if(b<=a)b=b.AddDays(1);return Math.Max(0,(b-a).TotalMinutes);}return 0;}}
public class ProductionOrderActualOption{public string BatchNumber{get;set;}=string.Empty;public int Id{get;set;}public int? RunSlotId{get;set;}public int SequenceNumber{get;set;}public string OrderNumber{get;set;}=string.Empty;public string Product{get;set;}=string.Empty;public string Unit{get;set;}=string.Empty;public string ArticleNumber{get;set;}=string.Empty;public DateTime PlannedDate{get;set;}public string WorkstationName{get;set;}=string.Empty;public string ShiftName{get;set;}=string.Empty;public double PlannedProductionMinutes{get;set;}public double DefaultIdealRatePerHour{get;set;}public string DisplayName=>$"{OrderNumber} · Schicht {SequenceNumber} · {PlannedDate:dd.MM.yyyy} · {ShiftName} · {Product}";}public class ProductionActualRow{public int Id{get;set;}public int ProductionOrderId{get;set;}public int? ProductionRunSlotId{get;set;}public DateTime Date{get;set;}public string OrderNumber{get;set;}=string.Empty;public string Product{get;set;}=string.Empty;public string Unit{get;set;}=string.Empty;public string ArticleNumber{get;set;}=string.Empty;public string BatchNumber{get;set;}=string.Empty;public string WorkstationName{get;set;}=string.Empty;public string ShiftName{get;set;}=string.Empty;public double TotalQuantity{get;set;}public double GoodQuantity{get;set;}public double ScrapQuantity{get;set;}public double PlannedProductionMinutes{get;set;}public double RunMinutes{get;set;}public double DowntimeMinutes{get;set;}public double IdealRatePerHour{get;set;}public double AvailabilityPercent{get;set;}public double PerformancePercent{get;set;}public double QualityPercent{get;set;}public double OeePercent{get;set;}public string? Comment{get;set;}public string QuantityText=>$"{TotalQuantity:N2} {Unit}";public string ScrapText=>$"{ScrapQuantity:N2} {Unit}";public string DowntimeText=>$"{DowntimeMinutes:N0} min";public string OeeText=>$"{OeePercent:N1} %";}public class DowntimeEntryRow{public int Id{get;set;}public int ProductionActualId{get;set;}public string Reason{get;set;}=string.Empty;public double Minutes{get;set;}public string? Comment{get;set;}public string MinutesText=>$"{Minutes:N0} min";}
